// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address actor) public {
        vm.assume(depositAmount <= VALUE_CAP);
        // Keep the search space wide but admissible.
        depositAmount = bound(depositAmount, 1, 1 ether);
        collectAmount = bound(collectAmount, 1, depositAmount);
        actor = address(uint160(uint256(keccak256(abi.encodePacked(actor))))) ;
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // Deploy a real LogFile so Log.AddMessage does not revert.
        LogFile log = new LogFile();

        // Setup per the reference's required ordering.
        c.SetLogFile(address(log));

        // Deposit exactly depositAmount from actor.
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // The only admissible collect amount is depositAmount, because MinSum defaults to 0
        // and Collect requires balances[actor] >= _am.
        collectAmount = depositAmount;

        uint256 contractBalanceBefore = address(c).balance;

        // Forge's address duplication is not an issue: each fuzz run is a fresh state.
        vm.prank(actor);
        c.Collect(collectAmount);

        uint256 contractBalanceAfter = address(c).balance;

        // GENERAL RULE: the contract pays out EXACTLY the requested amount _am.
        // In the reference, balanceBefore - balanceAfter == collectAmount.
        // In the mutant, Collect sends balances[msg.sender] after subtracting _am,
        // i.e. depositAmount - collectAmount = 0 here, so the balance drop is depositAmount,
        // which equals collectAmount only when collectAmount == depositAmount; with collectAmount < depositAmount
        // the mutant would violate this. We need a case where depositAmount > collectAmount to break it,
        // but Collect forbids that (requires balances[actor] >= _am and balances[actor] == depositAmount).
        // However, the mutant sends balances[msg.sender] AFTER subtracting _am: if depositAmount > collectAmount,
        // it would send less than _am, so balanceBefore - balanceAfter < collectAmount.
        // If depositAmount == collectAmount, the mutant sends 0 and the contract retains depositAmount,
        // so balanceBefore - balanceAfter > collectAmount.
        // The reference always sends exactly collectAmount.
        // The fuzzer will search for a case where the difference appears.
        assertTrue(contractBalanceBefore - contractBalanceAfter == collectAmount);
    }
}
